	if m.Metadata == nil {
		return trace.SpanContext{}, false
	}

	traceIDStr, ok1 := m.Metadata["trace_id"].(string)
	spanIDStr, ok2 := m.Metadata["span_id"].(string)
	if !ok1 || !ok2 {
		return trace.SpanContext{}, false
	}

	traceID, err := trace.TraceIDFromHex(traceIDStr)
