package kernel

import (
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"syscall"

	"github.com/james-nesbitt/alloy/api"
)

// SharedBuffer represents a memory-mapped buffer accessible by multiple plugins.
type SharedBuffer struct {
	ID           string
	Name         string
	Path         string
	Size         int
	Data         []byte
	File         *os.File
	LastModified int64
	Version      int
	History      []api.BufferChange
	mu           sync.RWMutex
	onUpdate     []func(id string, offset int, length int)
	manager      *BufferManager // Reference to parent for event broadcasting
}

// Satisfy SharedBuffer interface for api.SharedBuffer
func (b *SharedBuffer) GetID() string          { return b.ID }
func (b *SharedBuffer) GetName() string        { return b.Name }
func (b *SharedBuffer) GetData() []byte        { return b.Data }
func (b *SharedBuffer) GetSize() int           { return b.Size }
func (b *SharedBuffer) Lock()                  { b.mu.Lock() }
func (b *SharedBuffer) Unlock()                { b.mu.Unlock() }
func (b *SharedBuffer) GetVersion() int        { return b.Version }
func (b *SharedBuffer) GetLastModified() int64 { return b.LastModified }

func (b *SharedBuffer) OnUpdate(callback func(id string, offset int, length int)) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.onUpdate = append(b.onUpdate, callback)
}

func (b *SharedBuffer) triggerUpdate(offset, length int) {
	// Assumes lock is already held if called from internal methods,
	// but we should be careful.
	// To be safe, we'll copy the slice under lock and then execute outside.
	callbacks := make([]func(id string, offset int, length int), len(b.onUpdate))
	copy(callbacks, b.onUpdate)

	go func() {
		for _, cb := range callbacks {
			cb(b.ID, offset, length)
		}
	}()
}

// Resize increases the size of the shared buffer.
func (b *SharedBuffer) Resize(newSize int) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	err := b.resize(newSize)
	if err == nil {
		b.triggerUpdate(0, newSize)
	}
	return err
}

func (b *SharedBuffer) resize(newSize int) error {
	if newSize <= b.Size {
		return nil
	}

	// Unmap old data
	if b.Data != nil {
		if err := syscall.Munmap(b.Data); err != nil {
			return fmt.Errorf("failed to munmap old data: %w", err)
		}
	}

	// Truncate file
	if err := b.File.Truncate(int64(newSize)); err != nil {
		return fmt.Errorf("failed to truncate file: %w", err)
	}

	// Mmap new data
	data, err := syscall.Mmap(int(b.File.Fd()), 0, newSize, syscall.PROT_READ|syscall.PROT_WRITE, syscall.MAP_SHARED)
	if err != nil {
		return fmt.Errorf("failed to mmap resized file: %w", err)
	}

	b.Data = data
	b.Size = newSize
	return nil
}

// ApplyChange updates the buffer data and tracks the history for conflict resolution.
func (b *SharedBuffer) ApplyChange(change api.BufferChange) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	// Conflict Resolution Phase 12:
	// A change is "valid" even if stale if it doesn't overlap with any intermediate changes.
	if change.Version < b.Version {
		for i := len(b.History) - 1; i >= 0; i-- {
			hist := b.History[i]
			if hist.Version < change.Version {
				// History is sorted by version, we can stop once we're behind the incoming change.
				break
			}

			// Intersection check
			if (change.Offset < hist.Offset+len(hist.Data)) && (change.Offset+len(change.Data) > hist.Offset) {
				// We have a direct overlap. Use LWW (Last Write Wins) based on timestamp.
				// If the incoming change is physically older than a change we already applied to this region, we reject it.
				if change.Timestamp <= hist.Timestamp {
					return fmt.Errorf("buffer conflict: stale change (v%d) at offset %d overlaps with newer version (v%d)", change.Version, change.Offset, hist.Version)
				}
			}
		}
	}

	if change.Offset+len(change.Data) > b.Size {
		// Auto-resize for incoming changes
		if err := b.resize(change.Offset + len(change.Data) + 1024); err != nil {
			return err
		}
	}

	copy(b.Data[change.Offset:], change.Data)
	b.Version++
	b.LastModified = change.Timestamp

	// Track in history (Limited to last 100 changes for "lite" model)
	b.History = append(b.History, change)
	if len(b.History) > 100 {
		b.History = b.History[1:]
	}

	// Trigger callbacks and broadcast event for headless sync (Phase 12)
	b.triggerUpdate(change.Offset, len(change.Data))

	if b.manager != nil && b.manager.events != nil {
		eventData, _ := json.Marshal(map[string]any{
			"id":      b.ID,
			"offset":  change.Offset,
			"length":  len(change.Data),
			"version": b.Version,
			"actor":   change.Actor,
		})
		b.manager.events.Publish(context.Background(), "buffer:updated", "kernel", eventData)
	}

	return nil
}

// VisualIntent broadcasts a virtual cursor or highlight for this buffer (Phase 12)
func (b *SharedBuffer) VisualIntent(intent api.VisualIntent) error {
	if b.manager != nil && b.manager.events != nil {
		intent.BufferID = b.ID
		eventData, _ := json.Marshal(intent)
		b.manager.events.Publish(context.Background(), "visual:intent", "kernel", eventData)
	}
	return nil
}

// BufferManager handles the lifecycle of shared memory-mapped buffers.
type BufferManager struct {
	logger  *slog.Logger
	dataDir string
	buffers map[string]*SharedBuffer
	mu      sync.RWMutex
	events  *EventManager
}

// NewBufferManager creates a new BufferManager.
func NewBufferManager(logger *slog.Logger, dataDir string) *BufferManager {
	return &BufferManager{
		logger:  logger,
		dataDir: dataDir,
		buffers: make(map[string]*SharedBuffer),
	}
}

// SetEventManager attaches an EventManager for broadcasting (Phase 12)
func (bm *BufferManager) SetEventManager(e *EventManager) {
	bm.mu.Lock()
	defer bm.mu.Unlock()
	bm.events = e
}

// CreateBuffer creates or opens a memory-mapped buffer.
func (bm *BufferManager) CreateBuffer(id, name string, initialSize int) (api.SharedBuffer, error) {
	bm.mu.Lock()
	defer bm.mu.Unlock()

	if b, ok := bm.buffers[id]; ok {
		return b, nil
	}

	path := filepath.Join(bm.dataDir, "buffers", id+".data")
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return nil, fmt.Errorf("failed to create buffers dir: %w", err)
	}

	file, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		return nil, fmt.Errorf("failed to open buffer file: %w", err)
	}

	info, err := file.Stat()
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to stat buffer file: %w", err)
	}

	if initialSize <= 0 {
		initialSize = 1024 * 64 // Default to 64KB
	}

	if info.Size() < int64(initialSize) {
		if err := file.Truncate(int64(initialSize)); err != nil {
			file.Close()
			return nil, fmt.Errorf("failed to truncate buffer file: %w", err)
		}
	} else {
		initialSize = int(info.Size())
	}

	data, err := syscall.Mmap(int(file.Fd()), 0, initialSize, syscall.PROT_READ|syscall.PROT_WRITE, syscall.MAP_SHARED)
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to mmap buffer file: %w", err)
	}

	b := &SharedBuffer{
		ID:      id,
		Name:    name,
		Path:    path,
		Size:    initialSize,
		Data:    data,
		File:    file,
		manager: bm,
	}

	bm.buffers[id] = b
	bm.logger.Info("created shared mmap buffer", "id", id, "size", initialSize, "path", path)
	return b, nil
}

// GetBuffer retrieves a shared buffer by ID.
func (bm *BufferManager) GetBuffer(id string) (api.SharedBuffer, bool) {
	bm.mu.RLock()
	defer bm.mu.RUnlock()
	b, ok := bm.buffers[id]
	if !ok {
		return nil, false
	}
	return b, ok
}

// Write (Appends or Overwrites data)
func (b *SharedBuffer) Write(offset int, content []byte) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	if offset+len(content) > b.Size {
		return fmt.Errorf("buffer overflow: resize required")
	}

	copy(b.Data[offset:], content)
	b.Version++
	b.triggerUpdate(offset, len(content))
	return nil
}

// Close closes all buffers.
func (bm *BufferManager) Close() error {
	bm.mu.Lock()
	defer bm.mu.Unlock()

	for _, b := range bm.buffers {
		_ = syscall.Munmap(b.Data)
		_ = b.File.Close()
	}
	return nil
}

package api

import (
	"context"
	"encoding/json"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
)

// MessageType defines the type of message being sent.
type MessageType string

const (
	TypeRequest  MessageType = "request"
	TypeResponse MessageType = "response"
	TypeEvent    MessageType = "event"
)

// Message is the standard unit of communication in Alloy.
type Message struct {
	ID        string          `json:"id"`
	Type      MessageType     `json:"type"`
	Sender    string          `json:"sender"`
	Target    string          `json:"target,omitempty"`
	Method    string          `json:"method"`
	Payload   json.RawMessage `json:"payload,omitempty"`
	Timestamp int64           `json:"timestamp"`
	Metadata  map[string]any  `json:"metadata,omitempty"`
	Actor     string          `json:"actor,omitempty"`      // The identity performing the action (e.g., user email)
	SessionID string          `json:"session_id,omitempty"` // The unique session for the actor
}

// PluginLoadTime defines when a plugin should be loaded.
type PluginLoadTime string

const (
	LoadTimeBoot PluginLoadTime = "boot"
	LoadTimeLazy PluginLoadTime = "lazy"
)

// PluginMetadata describes a plugin's identity and capabilities before it is fully loaded.
type PluginMetadata struct {
	ID           string         `json:"id"`
	Capabilities []Capability   `json:"capabilities"`
	LoadTime     PluginLoadTime `json:"load_time"`
	Intents      []string       `json:"intents,omitempty"`    // Aggregated list of intents this plugin can handle (Phase 10)
	Background   bool           `json:"background,omitempty"` // Whether this plugin runs as a background actor (Phase 10)
	Sidecar      bool           `json:"sidecar,omitempty"`    // Whether this plugin is a global sidecar (Phase 10)
	Headless     bool           `json:"headless,omitempty"`   // Whether this plugin/client is headless (Phase 12)
}

// PluginLoader is an interface for components that can load a plugin on demand.
type PluginLoader interface {
	LoadPlugin(ctx context.Context, id string) (Plugin, error)
}

// Plugin defines the interface for components that can be registered with the kernel.
type Plugin interface {
	ID() string
	Capabilities() []Capability
	HandleMessage(ctx context.Context, msg Message) (Message, error)
	Shutdown(ctx context.Context) error
}

// ReadinessProvider is an optional interface for plugins that need time to
// initialize after loading but before receiving their first message.
type ReadinessProvider interface {
	Ready(ctx context.Context) error
}

func (m Message) ToSpanAttributes() []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("alloy.msg.id", m.ID),
		attribute.String("alloy.msg.sender", m.Sender),
		attribute.String("alloy.msg.target", m.Target),
		attribute.String("alloy.msg.method", m.Method),
		attribute.String("alloy.msg.type", string(m.Type)),
	}
}

// SpanContext returns an OpenTelemetry SpanContext if trace metadata is present in the message.
func (m Message) SpanContext() (trace.SpanContext, bool) {
	if m.Metadata == nil {
		return trace.SpanContext{}, false
	}

	traceIDStr, ok1 := m.Metadata["trace_id"].(string)
	spanIDStr, ok2 := m.Metadata["span_id"].(string)
	if !ok1 || !ok2 {
		return trace.SpanContext{}, false
	}

	traceID, err := trace.TraceIDFromHex(traceIDStr)
	if err != nil {
		return trace.SpanContext{}, false
	}
	spanID, err := trace.SpanIDFromHex(spanIDStr)
	if err != nil {
		return trace.SpanContext{}, false
	}

	return trace.NewSpanContext(trace.SpanContextConfig{
		TraceID: traceID,
		SpanID:  spanID,
		Remote:  true,
	}), true
}

// InjectSpanContext adds OpenTelemetry trace metadata to the message.
func (m *Message) InjectSpanContext(sc trace.SpanContext) {
	if m.Metadata == nil {
		m.Metadata = make(map[string]any)
	}
	m.Metadata["trace_id"] = sc.TraceID().String()
	m.Metadata["span_id"] = sc.SpanID().String()
}

// Interceptor is an optional interface that plugins can implement to intercept
// and potentially filter or modify messages before they are routed by the kernel.
type Interceptor interface {
	PreRoute(ctx context.Context, msg Message) (Message, bool, error)
}

// Capability describes a functionality provided by a component.
type Capability struct {
	Method      string            `json:"method,omitempty"`
	Description string            `json:"description,omitempty"`
	Shortcut    string            `json:"shortcut,omitempty"`    // Keyboard shortcut/mnemonic (e.g., "b l")
	Annotations map[string]string `json:"annotations,omitempty"` // Additional metadata (e.g., {"group": "buffers"})
	Intents     []string          `json:"intents,omitempty"`     // Intents satisfied by this method (Phase 10)
}

// Intent structure for goal-oriented routing (Phase 10)
type Intent struct {
	ID        string          `json:"id"`
	Name      string          `json:"name"` // e.g., "intent:save"
	Sender    string          `json:"sender"`
	Payload   json.RawMessage `json:"payload,omitempty"`
	ContextID string          `json:"context_id,omitempty"`
}

// Proposal represents a proactive suggestion from an actor (Phase 12)
type Proposal struct {
	ID          string          `json:"id"`
	Title       string          `json:"title"`       // e.g., "Fix Bug"
	Description string          `json:"description"` // e.g., "I noticed a security flaw, should I run an audit?"
	Action      string          `json:"action"`      // The intent name to trigger if accepted
	Payload     json.RawMessage `json:"payload,omitempty"`
	Metadata    map[string]any  `json:"metadata,omitempty"`
	Confidence  float32         `json:"confidence,omitempty"`
}

// Registration defines a component's presence in the system.
type Registration struct {
	ID           string       `json:"id"`
	Type         string       `json:"type"`
	Status       string       `json:"status,omitempty"`
	Capabilities []Capability `json:"capabilities,omitempty"`
	Background   bool         `json:"background,omitempty"` // Phase 10
	Sidecar      bool         `json:"sidecar,omitempty"`    // Phase 10
	Intents      []string     `json:"intents,omitempty"`    // Phase 10
	Headless     bool         `json:"headless,omitempty"`   // Phase 12
}

// WidgetUpdate represents a content refresh for a specific widget.
type WidgetUpdate struct {
	ID      string `json:"id"`
	Content []byte `json:"content"`
}

// Widget represents a dynamic dashboard tile.
type Widget struct {
	ID                string `json:"id"`
	Title             string `json:"title"`
	ContentType       string `json:"content_type"` // "markdown", "json", "ascii-art"
	Content           []byte `json:"content"`
	RefreshIntervalMs uint32 `json:"refresh_interval_ms"`
}

// MmapRegistry defines the interface for mapping buffers in WASM.
type MmapRegistry interface {
	GetBuffer(id string) (SharedBuffer, bool)
	CreateBuffer(id, name string, initialSize int) (SharedBuffer, error)
}

// SharedBuffer represents a host-side shared memory region.
type SharedBuffer interface {
	GetID() string
	GetName() string
	GetData() []byte
	GetSize() int
	Lock()
	Unlock()
	GetVersion() int
	GetLastModified() int64
	Resize(newSize int) error
	ApplyChange(change BufferChange) error
	OnUpdate(callback func(id string, offset int, length int))
}

// BufferChange represents a mutation to a buffer.
type BufferChange struct {
	Offset    int    `json:"offset"`
	Data      []byte `json:"data"`
	Version   int    `json:"version"`
	Actor     string `json:"actor"`
	Timestamp int64  `json:"timestamp"`
}

// Buffer reflects a handle to shared memory or file-backed storage
type Buffer struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	Content      []byte `json:"content"`
	Size         int    `json:"size"`
	LastModified int64  `json:"last_modified,omitempty"`
}

// VisualIntent represents a virtual cursor or highlight (Phase 12)
type VisualIntent struct {
	BufferID string `json:"buffer_id"`
	ActorID  string `json:"actor_id"`
	Type     string `json:"type"` // "cursor", "highlight"
	Offset   int    `json:"offset"`
	Length   int    `json:"length,omitempty"`
	Color    string `json:"color,omitempty"`
	Label    string `json:"label,omitempty"`
}

